  ('Business 1 (Basic Accounting)'),
  ('Business 2 (Business Finance and Income Taxation)'),
  ('Business 3 (Business Economics)'),
  ('Contemporary Marketing'),
  ('Design and Innovation'),
  ('Entrepreneurship'),
  ('Field Exposure (Off-Campus)'),
  ('Filipino Identity Through the Arts'),
  ('Introduction to Organization and Management'),
  ('Introduction to the Philosophy of Human Person'),
  ('Leadership and Management in the Arts'),
  ('Malikhaing Pagsulat'),
  ('Performance Criticism and Creative Markets'),
  ('Philippine Governance (Philippine Politics and Governance)'),
  ('Social Sciences (Theory and Practice)')
ON CONFLICT ((lower(btrim(name)))) DO NOTHING;

/* Grade 12: 239 */
INSERT INTO procurements.sms_competency_catalogue
  (learning_area_id, grade_level, lc_code, competency_text, term, week, domain)
SELECT a.id, v.grade_level::int, v.lc_code::text, v.competency_text::text, v.term::smallint, v.week::text, v.domain::text
FROM (VALUES
  ('Filipino Identity Through the Arts', 12, 'G12-001', 'Explain how geography, history, and institutions shape worldviews and cultural identity;', NULL, NULL, 'A. Definition and components of worldview B. Influence of geography (environment, location, and resources) on cultural practices and traditions C. Influence of historical events and colonization on identity formation D. Role of institutions (family, religion, education, and governance) in shaping values and beliefs E. Core concepts of the Filipino worldview (e.g., kapwa, bayanihan, and respect for elders) as reflected in cultural identity'),
  ('Filipino Identity Through the Arts', 12, 'G12-002', 'describe the significant features and characteristics of selected Philippine indigenous and traditional arts across performing, visual, literary, and architectural forms;', NULL, NULL, 'A. Elements and stylistic features of indigenous and traditional music (instruments, vocal forms, and functions) B. Movement vocabulary and functions of traditional dance C. Structure and performance conventions of traditional theater D. Materials, techniques, symbols, and motifs in indigenous and traditional visual arts E. Forms, themes, and oral traditions in indigenous and traditional literary arts F. Indigenous architectural forms, materials, spatial organization, and symbolism'),
  ('Filipino Identity Through the Arts', 12, 'G12-003', 'analyze how geographic, historical, cultural, political, economic, and social contexts are reflected in selected art forms;', NULL, NULL, 'A. Framework for contextual analysis of artworks B. Historical and socio-political influences in selected works C. Cultural beliefs, rituals, and community practices embedded in art forms D. Indigenous and traditional arts as repositories of collective memory E. Art as documentation of lived experiences and community narratives'),
  ('Filipino Identity Through the Arts', 12, 'G12-004', 'examine contemporary issues affecting indigenous and traditional arts;', NULL, NULL, 'A. Modernization, commercialization, and globalization as threats to continuity B. Cultural appropriation and misrepresentation C. Legal frameworks for heritage protection (Republic Act No. 10066 and related policies) D. Ethical considerations in adapting traditional elements for contemporary use'),
  ('Filipino Identity Through the Arts', 12, 'G12-005', 'evaluate the role of exemplary Filipino artists and community-based culture bearers in safeguarding heritage; and', NULL, NULL, 'A. Contributions of National Artists and Gawad sa Manlilikha ng Bayan (GAMABA) awardees to cultural preservation B. Role of community-based culture bearers in sustaining artistic traditions C. Processes of cultural transmission (apprenticeship, oral tradition, and communal practice) D. Sustainability and intergenerational continuity of indigenous and traditional arts'),
  ('Filipino Identity Through the Arts', 12, 'G12-006', 'design an integrated creative work inspired by indigenous and traditional arts using local materials, processes, and/or digital applications.', NULL, NULL, 'A. Concept development grounded in contextual research B. Selection and ethical integration of traditional elements C. Use of local materials, indigenous processes, and/or digital tools D. Production planning and execution E. Presentation, artist statement, and critical reflection'),
  ('Introduction to the Philosophy of Human Person', 12, 'G12-001', 'Recognize the value of understanding the nature and importance of doing Philosophy', NULL, NULL, 'Defining Philosophy ● Western and Eastern Beginnings of Doing Philosophy ● Branches of Philosophy ● Importance of Philosophy'),
  ('Introduction to the Philosophy of Human Person', 12, 'G12-002', 'Recognize the importance of analyzing the ways of doing Philosophy', NULL, NULL, 'Doing Philosophy ● Differentiating Truth and Opinion ● Differentiating Scientific or Factual Truth from Philosophical Truth Ways of Doing Philosophy ● Philosophical Analysis ● Philosophical Abstraction ● Philosophical Reflection'),
  ('Introduction to the Philosophy of Human Person', 12, 'G12-003', 'Recognize the importance of applying the ways of doing Philosophy on the Human Person as an embodied being in the world, with and for others, toward human and social flourishing', NULL, NULL, '1. The Human Person as Embodied Being in the World (zoon logon, pagkatao) a. Personhood ● Rationality (from awareness to creative rationality) ● Freedom (from choosing to creating) b. Human Personhood ● Embodiment ● Being in the Natural World (dweller and consumer) 2. The Human Person as Being With and for Others (zoon politikon, pagkamakatao) a. Interpersonal Relationships b. Institutional Relationships (economic, political, cultural) 3. The Meaning of Human Personhood a. Human Flourishing as Reason for Being ● What Human Flourishing ● Why Human Persons Flourish b. Human Person as Agent of Social Transformation ● Philosophies of Education on Human Flourishing ● The Filipino as a Thinker, Learner, and Social Change Agent'),
  ('Leadership and Management in the Arts', 12, 'G12-001', 'analyze the key functions of management and their application in arts organizations, productions, and events;', NULL, NULL, 'Management Basics A. Definition B. Objectives C. Functions 1. Planning a. Strategic management concepts in situation analysis internal and external 2. Organizing 3. Staffing 4. Directing 5. Controlling D. Leadership Roles and Functions'),
  ('Leadership and Management in the Arts', 12, 'G12-002', 'assess the internal and external conditions influencing the planning and execution of an artistic production;', NULL, NULL, 'Arts Production A. Examples of Arts Productions 1. Contextualizing arts production within environment B. Situational Analysis 1. The internal conditions of production a. Human resources and talents to hire b. Time c. Facilities and equipment d. Funds e. Technology 2. The external conditions of production a. Stakeholders b. Audience research c. Location 3. Socio-political-economic conditions'),
  ('Leadership and Management in the Arts', 12, 'G12-003', 'create a production management plan that outlines objectives, resource allocation, staffing, logistics, and evaluation strategies;', NULL, NULL, 'Production Brief 1. Rationale and objectives (S.M.A.R.T.) 2. Strategies (activities, steps, and tasks) 3. Setting targets and times 4. Production staff (structure) a. Vertically hierarchy b. Horizontal working and communication relationship 5. Output 6. Production costs and budget allocation 7. Risk management: Safety and security in the production site 8. Evaluation a. The importance of evaluating a production b. Indicators of success in a production C. Production Management Plan 1. Project title 2. Date, time, and venue 3. Artists and talents 4. Set design 5. Materials and resources needed 6. Technical requirements 7. Logistics 8. Communications 9. Budget and funding (include expenses: costume, venue styling, stage design, market and promotion, ticket design, etc.)'),
  ('Leadership and Management in the Arts', 12, 'G12-004', 'apply management skills and techniques to execute the production plan; and', NULL, NULL, 'A. Production Meeting 1. Creation of a production team 2. Assignment of roles and responsibilities 3. Dissemination of Tasks 4. Consideration of Production Requirements B. Production Implementation'),
  ('Leadership and Management in the Arts', 12, 'G12-005', 'evaluate the production by identifying its strengths and areas for improvement.', NULL, NULL, 'A. Evaluation of Production Resources and Processes: 1. Project title 2. Date, time, and venue 3. Artists and talents 4. Set design 5. Materials and resources Needed 6. Technical requirements 7. Logistics 8. Communications 9. Budget and funding B. Challenges of Production Management Execution 1. Promotion and marketing 2. Leadership roles and functions C. Arts Management in Organizations'),
  ('Malikhaing Pagsulat', 12, 'G12-001', 'Natutukoy ang mahahalagang detalye sa paligid sa pamamagitan ng pagmamasid', NULL, NULL, 'I. Mga Paghahanda sa Pagsulat A. Pagsasanay sa Paglalarawan 1. Pagmamasid sa Paligid 2. Paggamit ng Limang Pandama 3. Eksperimentasyon sa Imahen/Pagbuo ng Imahen Gamit ang Pagwawangis at Pagtutulad'),
  ('Malikhaing Pagsulat', 12, 'G12-002', 'Naipaliliwanag ang kahalagahan ng mga pandama sa paglalarawan', NULL, NULL, 'I. Mga Paghahanda sa Pagsulat A. Pagsasanay sa Paglalarawan 1. Pagmamasid sa Paligid 2. Paggamit ng Limang Pandama 3. Eksperimentasyon sa Imahen/Pagbuo ng Imahen Gamit ang Pagwawangis at Pagtutulad'),
  ('Malikhaing Pagsulat', 12, 'G12-003', 'Nagagamit ang limang pandama sa masining na paglalarawan ng paligid', NULL, NULL, 'I. Mga Paghahanda sa Pagsulat A. Pagsasanay sa Paglalarawan 1. Pagmamasid sa Paligid 2. Paggamit ng Limang Pandama 3. Eksperimentasyon sa Imahen/Pagbuo ng Imahen Gamit ang Pagwawangis at Pagtutulad'),
  ('Malikhaing Pagsulat', 12, 'G12-004', 'Nakabubuo ng mga imahen gamit ang pagwawangis at pagtutulad', NULL, NULL, 'I. Mga Paghahanda sa Pagsulat A. Pagsasanay sa Paglalarawan 1. Pagmamasid sa Paligid 2. Paggamit ng Limang Pandama 3. Eksperimentasyon sa Imahen/Pagbuo ng Imahen Gamit ang Pagwawangis at Pagtutulad'),
  ('Malikhaing Pagsulat', 12, 'G12-005', 'Natutukoy ang simula, gitna, at wakas ng mga naratibo', NULL, NULL, 'B. Pagsasanay sa Pagsasalaysay 1. Pagbabahagi ng mga Naratibo 1.1. Naratibong Biro (Narrative Jokes) 1.2. Personal na Alaala o Karanasan 2. Pagkatha ng mga Naratibo 2.1. Hakang Karanasan ng Iba (Makatotohanan) 2.2. Hakang Karanasan (Pantastiko)'),
  ('Malikhaing Pagsulat', 12, 'G12-006', 'Nakabubuo ng naratibong may tatlong pangungusap na may malinaw na simula, gitna, at wakas', NULL, NULL, 'B. Pagsasanay sa Pagsasalaysay 1. Pagbabahagi ng mga Naratibo 1.1. Naratibong Biro (Narrative Jokes) 1.2. Personal na Alaala o Karanasan 2. Pagkatha ng mga Naratibo 2.1. Hakang Karanasan ng Iba (Makatotohanan) 2.2. Hakang Karanasan (Pantastiko)'),
  ('Malikhaing Pagsulat', 12, 'G12-007', 'Nagagamit ang mga pamilyar na salaysay sa paghubog ng mga bagong tauhan', NULL, NULL, 'C. Pagsasanay sa Pagbuo ng Tauhan 1. Pagbibigay ng Modernong Katangian sa Tauhan mula sa mga Mito at/o Alamat 2. Paglalaro/Pagpapalit ng mga Tauhan 2.1. Bida at Kontrabida 2.2. Bagay o Hayop Bilang Tauhan'),
  ('Malikhaing Pagsulat', 12, 'G12-008', 'Natutukoy ang iba’t ibang uri ng sukat at tugma', NULL, NULL, 'D. Pagsasanay sa Pagbuo ng Taludtod 1. Paggamit ng Sukat at Tugma 1.1. Sukat (gaya ng pipituhin at wawaluhin) 1.2. Tugmang Malakas, Mahina, May Impit, at Walang Impit 2. Pagsasanay sa mga Bukal ng Pagtula 2.1. Bugtong 2.2. Salawikain'),
  ('Malikhaing Pagsulat', 12, 'G12-009', 'Nakabubuo ng modernong bugtong at/o salawikain na may wastong sukat at tugma', NULL, NULL, 'D. Pagsasanay sa Pagbuo ng Taludtod 1. Paggamit ng Sukat at Tugma 1.1. Sukat (gaya ng pipituhin at wawaluhin) 1.2. Tugmang Malakas, Mahina, May Impit, at Walang Impit 2. Pagsasanay sa mga Bukal ng Pagtula 2.1. Bugtong 2.2. Salawikain'),
  ('Malikhaing Pagsulat', 12, 'G12-010', 'Natutukoy ang persona o tinig sa tula', NULL, NULL, 'II. Pagsulat ng Tula A. Pagsasanay sa mga Anyong Tradisyonal'),
  ('Malikhaing Pagsulat', 12, 'G12-011', 'Naipaliliwanag ang pagkakaiba-iba ng mga himig sa tula', NULL, NULL, '1. Tanaga 2. Dalit 3. Awit B. Pagsasanay sa mga Anyong Moderno 1. Malayang Taludturan 2. Tulang Naratibo C. Pagsasanay sa mga Elemento ng Tula 1. Persona o Tinig 2. Himig 2.1. Nangangaral 2.2. Naglilimi 2.3. Nanghihimok 2.4. Naglalarawan 2.5. Nagpapatawa 2.6. Nang-uuyam D. Pagsasanay sa mga Anyong Postmoderno 1. Concrete Poetry 2. Spine Poem 3. Erasure Poetry'),
  ('Malikhaing Pagsulat', 12, 'G12-012', 'Nakabubuo ng mga tulang nasa anyong tradisyonal, moderno, at postmoderno', NULL, NULL, '1. Tanaga 2. Dalit 3. Awit B. Pagsasanay sa mga Anyong Moderno 1. Malayang Taludturan 2. Tulang Naratibo C. Pagsasanay sa mga Elemento ng Tula 1. Persona o Tinig 2. Himig 2.1. Nangangaral 2.2. Naglilimi 2.3. Nanghihimok 2.4. Naglalarawan 2.5. Nagpapatawa 2.6. Nang-uuyam D. Pagsasanay sa mga Anyong Postmoderno 1. Concrete Poetry 2. Spine Poem 3. Erasure Poetry'),
  ('Malikhaing Pagsulat', 12, 'G12-013', 'Naipaliliwanag ang pagkakaiba-iba ng mga popular na genre sa maikling kuwento', NULL, NULL, 'III. Pagsulat ng Maikling Kuwento A. Pagbubuo ng mga Tauhan 1. Protagonista/Bida 2. Antagonista/Kontrabida 3. Iba Pang Tauhan B. Pagpapasya sa Tagpuan 1. Panahon 2. Lunan/Lugar C. Paghubog ng Tunggalian 1. Tao Laban sa Sarili 2. Tao Laban sa Ibang Tao 3. Tao Laban sa Lipunan 4. Tao Laban sa Kalikasan 5. Tao Laban sa Tadhana'),
  ('Malikhaing Pagsulat', 12, 'G12-014', 'Naipaliliwanag ang pagkakaiba-iba ng mga uri ng tunggalian', NULL, NULL, 'III. Pagsulat ng Maikling Kuwento A. Pagbubuo ng mga Tauhan 1. Protagonista/Bida 2. Antagonista/Kontrabida 3. Iba Pang Tauhan B. Pagpapasya sa Tagpuan 1. Panahon 2. Lunan/Lugar C. Paghubog ng Tunggalian 1. Tao Laban sa Sarili 2. Tao Laban sa Ibang Tao 3. Tao Laban sa Lipunan 4. Tao Laban sa Kalikasan 5. Tao Laban sa Tadhana'),
  ('Malikhaing Pagsulat', 12, 'G12-015', 'Nagagamit ang angkop na punto de bista para sa binubuong kuwento', NULL, NULL, 'III. Pagsulat ng Maikling Kuwento A. Pagbubuo ng mga Tauhan 1. Protagonista/Bida 2. Antagonista/Kontrabida 3. Iba Pang Tauhan B. Pagpapasya sa Tagpuan 1. Panahon 2. Lunan/Lugar C. Paghubog ng Tunggalian 1. Tao Laban sa Sarili 2. Tao Laban sa Ibang Tao 3. Tao Laban sa Lipunan 4. Tao Laban sa Kalikasan 5. Tao Laban sa Tadhana'),
  ('Malikhaing Pagsulat', 12, 'G12-016', 'Nakapagbabalangkas ng banghay para sa binubuong maikling kuwento', NULL, NULL, 'III. Pagsulat ng Maikling Kuwento A. Pagbubuo ng mga Tauhan 1. Protagonista/Bida 2. Antagonista/Kontrabida 3. Iba Pang Tauhan B. Pagpapasya sa Tagpuan 1. Panahon 2. Lunan/Lugar C. Paghubog ng Tunggalian 1. Tao Laban sa Sarili 2. Tao Laban sa Ibang Tao 3. Tao Laban sa Lipunan 4. Tao Laban sa Kalikasan 5. Tao Laban sa Tadhana'),
  ('Malikhaing Pagsulat', 12, 'G12-017', 'Nakabubuo ng mga tauhan, tagpuan, at tunggalian para sa maikling kuwento', NULL, NULL, '6. Tao Laban sa Teknolohiya D. Pagbabalangkas ng Banghay 1. Eksposisyon/Panimula 2. Introduksiyon ng Tunggalian 3. Kaigtingan ng mga Pangyayari 4. Kasukdulan ng mga Pangyayari 5. Kakalasan ng mga Pangyayari 6. Resolusyon/Wakas E. Pagpapasya sa Punto de Bista 1. Unang Panauhan 2. Ikalawang Panauhan 3. Ikatlong Panauhan 3.1. Omniscient/Masaklaw na Pananaw 3.2. Limitadong Pananaw F. Eksperimentasyon sa mga Popular na Genre (hal., Fantasy, Horror, Sci-Fi, Detective Fiction, Romance)'),
  ('Malikhaing Pagsulat', 12, 'G12-018', 'Nakapagsusulat ng unang borador ng alinman sa koleksiyon ng mga tula o isang maikling kuwento.', NULL, NULL, 'Awtput: Unang borador ng alinman sa koleksiyon ng pitong'),
  ('Malikhaing Pagsulat', 12, 'G12-019', 'Naipaliliwanag ang halaga at mga katangian ng isang palihan', NULL, NULL, 'I. Paghahanda sa Palihan'),
  ('Malikhaing Pagsulat', 12, 'G12-020', 'Nasusuri ang mga puna at mungkahi na makatutulong sa rebisyon ng mga akda', NULL, NULL, 'II. Pagsasagawa ng Paglihan'),
  ('Malikhaing Pagsulat', 12, 'G12-021', 'Naibibigay ang mga makakabuluhang tanong at paglilinaw kaugnay ng akda', NULL, NULL, 'II. Pagsasagawa ng Paglihan'),
  ('Malikhaing Pagsulat', 12, 'G12-022', 'Natutukoy ang magkakatulad o magkakaugnay na puna at/o mungkahi mula sa palihan', NULL, NULL, 'III. Pagsasagawa ng Rebisyon'),
  ('Malikhaing Pagsulat', 12, 'G12-023', 'Nasusuri ang mga puna at mungkahi mula sa palihan ayon sa iba’t ibang uri ng usapin', NULL, NULL, 'III. Pagsasagawa ng Rebisyon'),
  ('Malikhaing Pagsulat', 12, 'G12-024', 'Nailalapat ang mga naisaayos na puna at mungkahi sa rebisyon ng unang borador', NULL, NULL, 'III. Pagsasagawa ng Rebisyon'),
  ('Malikhaing Pagsulat', 12, 'G12-025', 'Nakasusulat ng pinal na bersiyon ng malikhaing akda', NULL, NULL, 'Pinal na Awtput: Pinal na bersiyon ng alinman sa koleksiyon'),
  ('Performance Criticism and Creative Markets', 12, 'G12-001', 'construct a review of a music, dance, or theater performance;', NULL, NULL, 'I. Performance Criticism A. Definition of Performance Criticism B. Importance of Performance Criticism for Artists, Audiences, and the Creative Industries C. Qualifications of a Performance Critic D. Platfor ms for Performance Criticism 1. Live and Oral Platforms 2. Print Media Platforms 3. Digital and Online Platforms 4. Audio and Video Platforms 5. Academic and Educational Platforms 6. Community and Cultural Platforms'),
  ('Performance Criticism and Creative Markets', 12, 'G12-002', 'analyze the impact of various performing arts market trends on career opportunities, entrepreneurial pathways, and advocacy initiatives in the arts;', NULL, NULL, 'III. Performing Arts Markets A. Platform (Live, Hybrid, or Digital) B. Purpose (Non-Profit, Commercial, or Educational) C. Setting (Local/International) D. Audience Analysis 1. Demographics 2. Socio-Political Conditions 3. Economic Conditions'),
  ('Performance Criticism and Creative Markets', 12, 'G12-003', 'develop a persuasive pitch for an original performing arts work, highlighting its artistic elements and market relevance for potential industry audiences; and', NULL, NULL, 'V. Pitching Artistic Works A. Purpose of Pitching Artistic Works B. Elements of an Artistic Pitch 1. Concept or Idea of the Performance 2. Artistic elements and style 3. Target audience 4. Relevance to the market or platform C. Formats of Pitching 1. Verbal Pitch 2. Written Proposal or Concept Note 3. Digital Pitch Presentation D. Presenting an Artistic Pitch 1. Clarity of Ideas 2. Audience Awareness 3. Professional Presentation'),
  ('Performance Criticism and Creative Markets', 12, 'G12-004', 'curate a portfolio of performance critiques and creative market outputs demonstrating artistic discernment and market awareness. structured presentations or documents that communicate a creative concept, project, or production idea to potential collaborators, producers, funders, or institutions. research-based documents or visual materials that examine the characteristics, preferences, needs, and behaviors of intended audiences or markets for artistic or cultural products. the sector that produces cultural, artistic, and innovative goods and services derived from human creativity, skill, and talent and supported by intellectual property. an original product of human imagination and skill that expresses ideas through artistic, literary, musical, or design forms. the process of selecting, organizing, and presenting portfolio contents to communicate artistic insight and market understanding. the demand for, exchange of, and systems supporting creative works and services. the process of preparing a production for presentation or execution. spoken or multimedia-based evaluations that communicate insights and analyses about a performance, artwork, or creative work.', NULL, NULL, 'VI. Portfolio Development in Performance Criticism and Creative Markets A. Purpose of a Creative Portfolio 1. Documentation of Critical and Creative Work 2. Demonstrating Artistic Discernment and Market Awareness B. Types of Portfolio Entries 1. Written Performance Critiques 2. Oral or Digital Review Presentations 3. Artistic Pitch Proposals'),
  ('Philippine Governance (Philippine Politics and Governance)', 12, 'G12-001', 'Analyze the interplay of politics, power, and governance and their impact on society', NULL, NULL, 'The Concepts of Politics and Governance 1.1 The meaning of politics 1.2 The meaning of governance 1.3 The nature, dimensions, types, and consequences of power 1.4 Shared governance between government and citizens 2.1 The meaning of political ideology 2.2 The basic tenets of major political ideologies 2.3 The implications of ideology on governance and economic structures 3.1 State • The meaning of the State • The Elements of the State • The Philippine State Principles and Policies 3.2 Nation • The meaning of the Nation • The Philippines as a multiethnic nation • Indigenous Peoples • Muslim Communities 3.3 Relations between States and Nations • Globalization as a context for relations among states and nations • Issues in international relations (e.g., migration, security [wars and cybersecurity], public health [pandemics], climate change, human rights, and human trafficking)'),
  ('Philippine Governance (Philippine Politics and Governance)', 12, 'G12-002', 'Differentiate major political ideologies and explain how they influence governance systems in the Philippines and other parts of the world', NULL, NULL, 'The Concepts of Politics and Governance 1.1 The meaning of politics 1.2 The meaning of governance 1.3 The nature, dimensions, types, and consequences of power 1.4 Shared governance between government and citizens 2.1 The meaning of political ideology 2.2 The basic tenets of major political ideologies 2.3 The implications of ideology on governance and economic structures 3.1 State • The meaning of the State • The Elements of the State • The Philippine State Principles and Policies 3.2 Nation • The meaning of the Nation • The Philippines as a multiethnic nation • Indigenous Peoples • Muslim Communities 3.3 Relations between States and Nations • Globalization as a context for relations among states and nations • Issues in international relations (e.g., migration, security [wars and cybersecurity], public health [pandemics], climate change, human rights, and human trafficking)'),
  ('Philippine Governance (Philippine Politics and Governance)', 12, 'G12-003', 'Examine the concepts of the state and the nation and assess their implications for international relations', NULL, NULL, 'The Concepts of Politics and Governance 1.1 The meaning of politics 1.2 The meaning of governance 1.3 The nature, dimensions, types, and consequences of power 1.4 Shared governance between government and citizens 2.1 The meaning of political ideology 2.2 The basic tenets of major political ideologies 2.3 The implications of ideology on governance and economic structures 3.1 State • The meaning of the State • The Elements of the State • The Philippine State Principles and Policies 3.2 Nation • The meaning of the Nation • The Philippines as a multiethnic nation • Indigenous Peoples • Muslim Communities 3.3 Relations between States and Nations • Globalization as a context for relations among states and nations • Issues in international relations (e.g., migration, security [wars and cybersecurity], public health [pandemics], climate change, human rights, and human trafficking)'),
  ('Philippine Governance (Philippine Politics and Governance)', 12, 'G12-004', 'Analyze how the 1987 Constitution functions as a social contract that protects human rights and promotes the rule of law within a Philippine constitutional democracy', NULL, NULL, '4.1 The 1987 Philippine Constitution as a social contract 4.2 The Philippines as a constitutional democracy'),
  ('Philippine Governance (Philippine Politics and Governance)', 12, 'G12-005', 'Explain the principle of separation of powers and the system of checks and balances among the three branches of government in promoting accountability, preventing the abuse of power, and ensuring good governance', NULL, NULL, '5.1 The separation of powers as a fundamental principle in a democratic government 5.2 The principle of checks and balances and its provisions as expressed in the 1987 Constitution 6.1 The key elements of the presidential form of government 6.2 The roles and powers of the Philippine President and Vice President 6.3 The role of the Cabinet and the functions of government agencies 7.1 The bicameral legislative system (upper and lower houses) 7.2 The leadership, structure, roles, and responsibilities of the Philippine Senate 7.3 The leadership, structure, roles, and responsibilities of the House of Representatives 8.1 The leadership, structure, roles, and responsibilities of the Philippine Judiciary 9.1 The features of decentralization in the Philippines 9.2 The structure of local governments in the context of the Local Government Code of 1991'),
